"""Characterization tests generated by Inherit.

Each test pins behavior OBSERVED when the code ran; it records what the code does today,
not what it should do. Review tests marked REVIEW before treating them as correct.
Module state and the environment variables a call read are reset to what was recorded when
it was observed (monkeypatch restores them afterwards), so these tests neither depend on nor
leak into other tests' state.
"""
import copy

import pytest
import vault.strings

# REVIEW: raises TypeError for these inputs; confirm this is intended
def test_vault_strings_mask_case_1():  # evidence: E-0025, E-0026
    with pytest.raises(TypeError) as info:
        vault.strings.mask(1)
    assert str(info.value) == "object of type 'int' has no len()"

def test_vault_strings_mask_case_2():  # evidence: E-0025, E-0026
    assert vault.strings.mask('a') == '*'

# REVIEW: raises AttributeError for these inputs; confirm this is intended
def test_vault_strings_fingerprint_case_1():  # evidence: E-0027, E-0028
    with pytest.raises(AttributeError) as info:
        vault.strings.fingerprint(1)
    assert str(info.value) == "'int' object has no attribute 'encode'"

def test_vault_strings_fingerprint_case_2():  # evidence: E-0027, E-0028
    assert vault.strings.fingerprint('a') == 'ca978112ca1b'
